// Baut aus den Rechnungsdaten eine HTML-Seite. Gotenberg macht daraus das PDF.
// Absenderdaten: bitte vor dem echten Einsatz ersetzen!
const ABSENDER = {
  name: 'Gebäudeservice (Demo)',
  adresse: 'Musterstraße 0, 45000 Essen',
  steuernummer: 'Steuernummer: 000/0000/0000',
  iban: 'IBAN: DE00 0000 0000 0000 0000 00',
};

const r = $input.first().json;

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const eur = (n) => Number(n).toLocaleString('de-DE', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' €';

const zeilen = r.positionen.map((p, i) =>
  `<tr><td>${i + 1}</td><td>${esc(p.beschreibung)}</td>` +
  `<td class="r">${esc(p.menge)} ${esc(p.einheit)}</td>` +
  `<td class="r">${eur(p.einzelpreis)}</td><td class="r">${eur(p.summe)}</td></tr>`
).join('');

const html = `<!DOCTYPE html>
<html lang="de"><head><meta charset="utf-8"><title>${esc(r.rechnungsnummer)}</title>
<style>
  body { font-family: Helvetica, Arial, sans-serif; font-size: 11pt; color: #222; }
  h1 { font-size: 20pt; margin: 30px 0 4px; }
  .absender { font-size: 9pt; color: #555; border-bottom: 1px solid #aaa; padding-bottom: 4px; }
  .meta { margin: 16px 0; }
  table { width: 100%; border-collapse: collapse; margin-top: 18px; }
  th { text-align: left; border-bottom: 2px solid #222; padding: 6px 4px; }
  td { padding: 6px 4px; border-bottom: 1px solid #ddd; }
  .r { text-align: right; }
  .summen { width: 45%; margin-left: 55%; }
  .summen td { border: none; }
  .gesamt td { border-top: 2px solid #222; font-weight: bold; }
  .demo { margin-top: 40px; font-size: 9pt; color: #b00020; }
  .fuss { margin-top: 30px; font-size: 9pt; color: #555; }
</style></head>
<body>
  <div class="absender">${esc(ABSENDER.name)} · ${esc(ABSENDER.adresse)}</div>
  <div class="meta">
    ${esc(r.firmenname)}<br>${esc(r.strasse)}<br>${esc(r.plz)} ${esc(r.ort)}
  </div>
  <h1>Rechnung ${esc(r.rechnungsnummer)}</h1>
  <div>Rechnungsdatum: ${esc(r.rechnungsdatum)} · Leistungsmonat: ${esc(r.leistungsmonat)}</div>
  <table>
    <tr><th>Pos.</th><th>Beschreibung</th><th class="r">Menge</th><th class="r">Einzelpreis</th><th class="r">Summe</th></tr>
    ${zeilen}
  </table>
  <table class="summen">
    <tr><td>Netto</td><td class="r">${eur(r.netto)}</td></tr>
    <tr><td>Umsatzsteuer ${esc(r.ust_satz)} %</td><td class="r">${eur(r.ust)}</td></tr>
    <tr class="gesamt"><td>Gesamtbetrag</td><td class="r">${eur(r.brutto)}</td></tr>
  </table>
  <div class="fuss">
    Zahlbar bis ${esc(r.faellig_am)} ohne Abzug.<br>
    ${esc(ABSENDER.steuernummer)} · ${esc(ABSENDER.iban)}
  </div>
  <div class="demo">Demo-Rechnung mit fiktiven Daten, keine rechtsgültige Rechnung.</div>
</body></html>`;

return [{ json: { ...r, html } }];
